# -*- coding: utf-8 -*-
# GENERATED BY AI
"""KiCad footprint rendering.

Renders a KiCad footprint (``.kicad_mod`` file, e.g. from a ``.pretty``
footprint library) as a top-view SVG image, showing copper pads (including
drill holes and pad numbers), silkscreen, fabrication layer, and courtyard
graphics. Used by the connector ``footprint`` attribute; see
``docs/syntax.md``.

Parsing relies on the ``kiutils`` package (https://github.com/mvnmgrx/kiutils).
"""

import hashlib
import math
import tempfile
from pathlib import Path
from typing import Dict, List, Optional, Tuple

from kiutils.footprint import Footprint

# Colors used when rendering the footprint (top view on a light background)
COLOR_PAD = "#b87333"  # copper pads
COLOR_HOLE = "#ffffff"  # drill holes
COLOR_HOLE_OUTLINE = "#555555"  # outline of non-plated holes
COLOR_SILKSCREEN = "#333333"  # F.SilkS graphics
COLOR_FAB = "#777777"  # F.Fab graphics
COLOR_COURTYARD = "#999999"  # F.Courtyard graphics
COLOR_TEXT_ON_PAD = "#ffffff"  # pad numbers on copper
COLOR_TEXT_ON_BACKGROUND = "#333333"  # pad numbers on non-copper pads

DEFAULT_LINE_WIDTH = 0.12  # mm, KiCad's default for footprint graphics
DEFAULT_PAD_ROUNDRECT_RATIO = 0.25
DEFAULT_IMAGE_WIDTH = 120  # points, like WireViz image width attribute;
# sized to fit within a typical connector node, rendering KiCad's default
# 1.27 mm pin text at roughly the size of the diagram's table text
MARGIN = 0.25  # mm between footprint bounding box and SVG border

# Keys allowed in the YAML footprint attribute
FOOTPRINT_ATTRIBUTE_KEYS = {"library", "part", "width", "height", "bgcolor", "caption"}


def _fmt(value: float) -> str:
    """Format a float without trailing zeros for use in SVG output."""
    return f"{value:.4f}".rstrip("0").rstrip(".") or "0"


def _escape(text: str) -> str:
    """Escape a string for use in SVG text content."""
    return (
        str(text)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def _item_width(item) -> float:
    """Return the stroke width of a footprint graphic item in mm."""
    width = getattr(item, "width", None)
    if width is None and getattr(item, "stroke", None) is not None:
        width = item.stroke.width
    return float(width) if width is not None else DEFAULT_LINE_WIDTH


def _stroke_type(item) -> Optional[str]:
    """Return the stroke type (dash style) of a footprint graphic item, if any."""
    stroke = getattr(item, "stroke", None)
    return stroke.type if stroke is not None else None


def _dasharray(item) -> Optional[str]:
    """Map the KiCad stroke type of an item to an SVG stroke-dasharray."""
    stroke_type = _stroke_type(item)
    width = _item_width(item)
    if stroke_type == "dash":
        return f"{_fmt(3 * width)},{_fmt(2 * width)}"
    if stroke_type == "dot":
        return f"{_fmt(0.5 * width)},{_fmt(1.5 * width)}"
    if stroke_type == "dash_dot":
        return f"{_fmt(3 * width)},{_fmt(1.5 * width)},{_fmt(0.5 * width)},{_fmt(1.5 * width)}"
    if stroke_type == "dash_dot_dot":
        return f"{_fmt(3 * width)},{_fmt(1.5 * width)},{_fmt(0.5 * width)},{_fmt(1.5 * width)},{_fmt(0.5 * width)},{_fmt(1.5 * width)}"
    return None  # solid or unknown


class _Renderer:
    """Collects SVG fragments and the bounding box while walking the footprint."""

    def __init__(self, footprint: Footprint):
        self.footprint = footprint
        self.min_x = math.inf
        self.min_y = math.inf
        self.max_x = -math.inf
        self.max_y = -math.inf
        self.courtyard: List[str] = []
        self.fab: List[str] = []
        self.silkscreen: List[str] = []
        self.pads: List[str] = []
        self.pad_numbers: List[str] = []

    # -- bounding box ------------------------------------------------------

    def _track(self, x: float, y: float) -> None:
        self.min_x = min(self.min_x, x)
        self.min_y = min(self.min_y, y)
        self.max_x = max(self.max_x, x)
        self.max_y = max(self.max_y, y)

    def _track_item(self, x: float, y: float, width: float) -> None:
        """Track a line/outline position including half the stroke width."""
        half = width / 2
        self._track(x - half, y - half)
        self._track(x + half, y + half)

    # -- graphics items ----------------------------------------------------

    def _line(self, item, color: str, dashed: bool) -> str:
        start, end = item.start, item.end
        width = _item_width(item)
        for point in (start, end):
            self._track_item(point.X, point.Y, width)
        extra = f' stroke-dasharray="{_dasharray(item)}"' if dashed and _dasharray(item) else ""
        return (
            f'<line x1="{_fmt(start.X)}" y1="{_fmt(start.Y)}" '
            f'x2="{_fmt(end.X)}" y2="{_fmt(end.Y)}" '
            f'stroke="{color}" stroke-width="{_fmt(width)}"{extra}/>'
        )

    def _rect(self, item, color: str, dashed: bool) -> str:
        start, end = item.start, item.end
        width = _item_width(item)
        for point in (start, end):
            self._track_item(point.X, point.Y, width)
        x, y = min(start.X, end.X), min(start.Y, end.Y)
        w, h = abs(end.X - start.X), abs(end.Y - start.Y)
        fill = color if getattr(item, "fill", None) == "solid" else "none"
        extra = f' stroke-dasharray="{_dasharray(item)}"' if dashed and _dasharray(item) else ""
        return (
            f'<rect x="{_fmt(x)}" y="{_fmt(y)}" width="{_fmt(w)}" height="{_fmt(h)}" '
            f'fill="{fill}" stroke="{color}" stroke-width="{_fmt(width)}"{extra}/>'
        )

    def _circle(self, item, color: str, dashed: bool) -> str:
        center, end = item.center, item.end
        width = _item_width(item)
        radius = math.hypot(end.X - center.X, end.Y - center.Y)
        for dx, dy in ((-radius, -radius), (radius, radius)):
            self._track_item(center.X + dx, center.Y + dy, width)
        fill = color if getattr(item, "fill", None) == "solid" else "none"
        extra = f' stroke-dasharray="{_dasharray(item)}"' if dashed and _dasharray(item) else ""
        return (
            f'<circle cx="{_fmt(center.X)}" cy="{_fmt(center.Y)}" r="{_fmt(radius)}" '
            f'fill="{fill}" stroke="{color}" stroke-width="{_fmt(width)}"{extra}/>'
        )

    def _arc(self, item, color: str, dashed: bool) -> str:
        start, mid, end = item.start, item.mid, item.end
        width = _item_width(item)
        for point in (start, mid, end):
            self._track_item(point.X, point.Y, width)
        center = self._circumcenter(
            (start.X, start.Y), (mid.X, mid.Y), (end.X, end.Y)
        )
        if center is None:  # collinear points, fall back to a line
            return self._line(item, color, dashed)
        radius = math.hypot(start.X - center[0], start.Y - center[1])
        a0 = math.atan2(start.Y - center[1], start.X - center[0])
        am = math.atan2(mid.Y - center[1], mid.X - center[0])
        a1 = math.atan2(end.Y - center[1], end.X - center[0])
        to_end = self._norm(a1 - a0)  # span when going in positive direction
        to_mid = self._norm(am - a0)
        if to_mid <= to_end:  # mid point is on the positive-direction arc
            sweep, span = 1, to_end
        else:
            sweep, span = 0, 2 * math.pi - to_end
        large = 1 if span > math.pi else 0
        extra = f' stroke-dasharray="{_dasharray(item)}"' if dashed and _dasharray(item) else ""
        return (
            f'<path d="M {_fmt(start.X)} {_fmt(start.Y)} '
            f'A {_fmt(radius)} {_fmt(radius)} 0 {large} {sweep} '
            f'{_fmt(end.X)} {_fmt(end.Y)}" fill="none" '
            f'stroke="{color}" stroke-width="{_fmt(width)}"{extra}/>'
        )

    @staticmethod
    def _norm(angle: float) -> float:
        while angle < 0:
            angle += 2 * math.pi
        while angle >= 2 * math.pi:
            angle -= 2 * math.pi
        return angle

    @staticmethod
    def _circumcenter(p0, p1, p2) -> Optional[Tuple[float, float]]:
        d = 2 * (p0[0] * (p1[1] - p2[1]) + p1[0] * (p2[1] - p0[1]) + p2[0] * (p0[1] - p1[1]))
        if abs(d) < 1e-12:
            return None
        a2 = p0[0] ** 2 + p0[1] ** 2
        b2 = p1[0] ** 2 + p1[1] ** 2
        c2 = p2[0] ** 2 + p2[1] ** 2
        ux = (a2 * (p1[1] - p2[1]) + b2 * (p2[1] - p0[1]) + c2 * (p0[1] - p1[1])) / d
        uy = (a2 * (p2[0] - p1[0]) + b2 * (p0[0] - p2[0]) + c2 * (p1[0] - p0[0])) / d
        return (ux, uy)

    def _poly(self, item, color: str, dashed: bool) -> str:
        width = _item_width(item)
        for point in item.coordinates:
            self._track_item(point.X, point.Y, width)
        points = " ".join(f"{_fmt(p.X)},{_fmt(p.Y)}" for p in item.coordinates)
        fill = color if getattr(item, "fill", None) == "solid" else "none"
        extra = f' stroke-dasharray="{_dasharray(item)}"' if dashed and _dasharray(item) else ""
        return (
            f'<polygon points="{points}" fill="{fill}" '
            f'stroke="{color}" stroke-width="{_fmt(width)}"{extra}/>'
        )

    def _curve(self, item, color: str, dashed: bool) -> str:
        # Approximated as a polyline; cubic bezier curves are rare in footprints
        width = _item_width(item)
        for point in item.coordinates:
            self._track_item(point.X, point.Y, width)
        points = " ".join(f"{_fmt(p.X)},{_fmt(p.Y)}" for p in item.coordinates)
        extra = f' stroke-dasharray="{_dasharray(item)}"' if dashed and _dasharray(item) else ""
        return (
            f'<polyline points="{points}" fill="none" '
            f'stroke="{color}" stroke-width="{_fmt(width)}"{extra}/>'
        )

    # -- pads --------------------------------------------------------------

    def _pad(self, pad) -> None:
        position = pad.position
        w, h = float(pad.size.X), float(pad.size.Y)
        angle = float(position.angle) if position.angle is not None else 0
        copper = pad.type != "np_thru_hole"

        # Track bounding box (rotated square that contains the pad)
        half = math.hypot(w, h) / 2
        self._track(position.X - half, position.Y - half)
        self._track(position.X + half, position.Y + half)

        group = [
            f'<g transform="translate({_fmt(position.X)} {_fmt(position.Y)}) '
            f'rotate({_fmt(-angle)})">'
        ]
        if copper:
            group.append(self._pad_shape(pad, w, h))
        if pad.drill is not None and pad.drill.diameter:
            group.append(self._pad_drill(pad, copper))
        group.append("</g>")
        self.pads.append("".join(group))

        self._pad_number(pad, position, w, h, copper)

    def _pad_shape(self, pad, w: float, h: float) -> str:
        shape = pad.shape
        if shape == "circle":
            return (
                f'<circle cx="0" cy="0" r="{_fmt(max(w, h) / 2)}" '
                f'fill="{COLOR_PAD}"/>'
            )
        if shape == "oval":  # stadium shape
            radius = min(w, h) / 2
            return self._pad_rect(w, h, radius)
        if shape == "roundrect":
            ratio = (
                pad.roundrectRatio
                if pad.roundrectRatio is not None
                else DEFAULT_PAD_ROUNDRECT_RATIO
            )
            radius = min(w, h) / 2 * float(ratio)
            return self._pad_rect(w, h, radius)
        if shape == "custom":
            parts = [self._custom_pad_anchor(pad, w, h)]
            parts.extend(self._custom_pad_primitives(pad))
            return "".join(parts)
        # rect and trapezoid (rect_delta is not exposed by kiutils and is
        # deprecated by KiCad, so trapezoid pads are drawn as rectangles)
        return self._pad_rect(w, h, 0)

    @staticmethod
    def _pad_rect(w: float, h: float, radius: float) -> str:
        rounded = f' rx="{_fmt(radius)}"' if radius else ""
        return (
            f'<rect x="{_fmt(-w / 2)}" y="{_fmt(-h / 2)}" width="{_fmt(w)}" '
            f'height="{_fmt(h)}"{rounded} fill="{COLOR_PAD}"/>'
        )

    def _custom_pad_anchor(self, pad, w: float, h: float) -> str:
        anchor = (
            pad.customPadOptions.anchor
            if pad.customPadOptions is not None
            else "rect"
        )
        if anchor == "circle":
            return f'<circle cx="0" cy="0" r="{_fmt(max(w, h) / 2)}" fill="{COLOR_PAD}"/>'
        return self._pad_rect(w, h, 0)

    def _custom_pad_primitives(self, pad) -> List[str]:
        parts = []
        for primitive in pad.customPadPrimitives:
            coordinates = getattr(primitive, "coordinates", None)
            if coordinates:  # polygon primitives
                points = " ".join(f"{_fmt(p.X)},{_fmt(p.Y)}" for p in coordinates)
                parts.append(f'<polygon points="{points}" fill="{COLOR_PAD}"/>')
            # other custom pad primitive types are not rendered
        return parts

    def _pad_drill(self, pad, copper: bool) -> str:
        drill = pad.drill
        offset = drill.offset
        cx = _fmt(offset.X) if offset is not None else "0"
        cy = _fmt(offset.Y) if offset is not None else "0"
        outline = (
            f' stroke="{COLOR_HOLE_OUTLINE}" stroke-width="0.1"'
            if not copper  # non-plated holes get a visible outline
            else ""
        )
        if drill.oval and drill.width:
            return (
                f'<ellipse cx="{cx}" cy="{cy}" rx="{_fmt(drill.diameter / 2)}" '
                f'ry="{_fmt(drill.width / 2)}" fill="{COLOR_HOLE}"{outline}/>'
            )
        return (
            f'<circle cx="{cx}" cy="{cy}" r="{_fmt(drill.diameter / 2)}" '
            f'fill="{COLOR_HOLE}"{outline}/>'
        )

    def _pad_number(self, pad, position, w: float, h: float, copper: bool) -> None:
        if not pad.number or pad.number == "~":
            return
        font_size = min(0.8 * min(w, h), 1.27)  # mm, capped like KiCad text
        if font_size < 0.4:
            return  # pad too small for a legible number
        drilled = pad.drill is not None and pad.drill.diameter
        if not copper or drilled:
            # non-plated pads and drilled pads show their number over the
            # light hole, everything else over the copper pad
            color = COLOR_TEXT_ON_BACKGROUND
        else:
            color = COLOR_TEXT_ON_PAD
        self.pad_numbers.append(
            f'<text x="{_fmt(position.X)}" y="{_fmt(position.Y)}" '
            f'font-family="sans-serif" font-size="{_fmt(font_size)}" '
            f'fill="{color}" text-anchor="middle" dominant-baseline="central">'
            f"{_escape(pad.number)}</text>"
        )

    # -- assembly ----------------------------------------------------------

    def run(self) -> Tuple[str, float, float]:
        for item in self.footprint.graphicItems:
            layer = getattr(item, "layer", None)
            if not layer:
                continue  # e.g. fp_text (not rendered) or embedded images
            if layer.startswith("F.Courtyard") or layer.startswith("F.CrtYd"):
                target, color, dashed = self.courtyard, COLOR_COURTYARD, True
            elif layer.startswith("F.Fab"):
                target, color, dashed = self.fab, COLOR_FAB, False
            elif layer.startswith("F.Silk"):
                target, color, dashed = self.silkscreen, COLOR_SILKSCREEN, False
            else:
                continue  # only front side layers are rendered
            name = item.__class__.__name__
            if name == "FpLine":
                target.append(self._line(item, color, dashed))
            elif name == "FpRect":
                target.append(self._rect(item, color, dashed))
            elif name == "FpCircle":
                target.append(self._circle(item, color, dashed))
            elif name == "FpArc":
                target.append(self._arc(item, color, dashed))
            elif name == "FpPoly":
                target.append(self._poly(item, color, dashed))
            elif name == "FpCurve":
                target.append(self._curve(item, color, dashed))
            # other graphic item types are not rendered

        for pad in self.footprint.pads:
            self._pad(pad)

        if self.min_x is math.inf:  # empty footprint
            self.min_x = self.min_y = -1.0
            self.max_x = self.max_y = 1.0

        min_x = self.min_x - MARGIN
        min_y = self.min_y - MARGIN
        width = self.max_x - self.min_x + 2 * MARGIN
        height = self.max_y - self.min_y + 2 * MARGIN

        svg = [
            # The XML declaration is required for Graphviz to recognize the
            # file as an SVG image (it detects the type by magic header).
            '<?xml version="1.0" encoding="UTF-8"?>',
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{_fmt(width)}mm" '
            f'height="{_fmt(height)}mm" viewBox="{_fmt(min_x)} {_fmt(min_y)} '
            f'{_fmt(width)} {_fmt(height)}">',
            *self.courtyard,
            *self.fab,
            *self.silkscreen,
            *self.pads,
            *self.pad_numbers,
            "</svg>",
        ]
        return "".join(svg), width, height


def render_footprint_svg(footprint: Footprint) -> Tuple[str, float, float]:
    """Render a KiCad footprint (parsed by kiutils) as a top-view SVG image.

    Returns the SVG document as a string, plus its width and height in mm.
    """
    return _Renderer(footprint).run()


def footprint_image(spec: Dict):
    """Create a WireViz Image by loading and rendering a KiCad footprint.

    ``spec`` is the value of the connector ``footprint`` attribute:
    a dict with a ``library`` (path to a ``.pretty`` footprint library
    directory or directly to a ``.kicad_mod`` file), optionally a ``part``
    (footprint name within the library), and optional ``width``, ``height``,
    ``bgcolor``, and ``caption`` for the resulting image.
    """
    from wireviz.DataClasses import Image  # imported here to avoid circular imports

    unknown = set(spec) - FOOTPRINT_ATTRIBUTE_KEYS
    if unknown:
        raise ValueError(
            f"Unknown footprint attribute(s): {', '.join(sorted(unknown))}"
        )

    library = spec.get("library")
    part = spec.get("part")
    if not library:
        raise ValueError("The footprint attribute requires a 'library'")
    library_path = Path(str(library))
    footprint_file = library_path
    if footprint_file.suffix != ".kicad_mod":
        if not part:
            raise ValueError(
                "The footprint attribute requires a 'part' when 'library' "
                "is a footprint library directory"
            )
        footprint_file = library_path / f"{part}.kicad_mod"
    if not footprint_file.is_file():
        raise FileNotFoundError(
            f"KiCad footprint not found: {footprint_file}"
        )

    footprint = Footprint.from_file(str(footprint_file))
    svg, width_mm, height_mm = render_footprint_svg(footprint)

    # Cache the rendered SVG, one file per unique rendering
    cache_dir = Path(tempfile.gettempdir()) / "wireviz-footprints"
    cache_dir.mkdir(parents=True, exist_ok=True)
    digest = hashlib.sha256(svg.encode("utf-8")).hexdigest()[:8]
    svg_file = cache_dir / f"{footprint_file.stem}-{digest}.svg"
    if not svg_file.exists():
        svg_file.write_text(svg, encoding="utf-8")

    width = spec.get("width") or DEFAULT_IMAGE_WIDTH
    height = spec.get("height") or round(width * height_mm / width_mm)
    return Image(
        src=str(svg_file),
        width=int(width),
        height=int(height),
        bgcolor=spec.get("bgcolor"),
        caption=spec.get("caption"),
    )
